{"path": "bowling.py", "content": "class BowlingGame:
    def __init__(self):
        self.rolls = []

    def _state(self, rolls):
        """Walk the rolls and return (frame_index, rolls_in_current_frame, complete)."""
        i = 0
        frame = 0
        while frame < 9:
            if i >= len(rolls):
                return frame, rolls[i:], False
            if rolls[i] == 10:
                i += 1
            else:
                if i + 1 >= len(rolls):
                    return frame, rolls[i:], False
                i += 2
            frame += 1
        tenth = rolls[i:]
        needed = 2
        if len(tenth) >= 2 and (tenth[0] == 10 or tenth[0] + tenth[1] == 10):
            needed = 3
        return 9, tenth, len(tenth) >= needed

    def roll(self, pins):
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("negative roll is invalid")
        if pins > 10:
            raise ValueError("pin count exceeds pins on the lane")
        frame, current, complete = self._state(self.rolls)
        if complete:
            raise IndexError("cannot roll after game is over")
        if frame < 9:
            if len(current) == 1 and current[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
        else:
            if len(current) == 1 and current[0] < 10 and current[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
            if len(current) == 2:
                first, second = current
                if first == 10 and second < 10 and second + pins > 10:
                    raise ValueError("pin count exceeds pins on the lane")
        self.rolls.append(pins)

    def score(self):
        _, _, complete = self._state(self.rolls)
        if not complete:
            raise IndexError("an incomplete game cannot be scored")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
